--
-- Estructura de tabla para la tabla `m_ayuntamientos`
--

CREATE TABLE `m_ayuntamientos` (
  `IDAYUNTAMIENTO` int(11) NOT NULL,
  `REFERENCIA` varchar(100) DEFAULT NULL,
  `N_AYUNTAMIENTO` varchar(100) DEFAULT NULL,
  `CCAA` varchar(100) DEFAULT NULL,
  `ALCALDE` varchar(100) DEFAULT NULL,
  `P_CONTACTO` varchar(10) DEFAULT NULL,
  `CARGO` varchar(100) DEFAULT NULL,
  `TLF_FIJO` varchar(20) DEFAULT NULL,
  `TLF_MOVIL` varchar(20) DEFAULT NULL,
  `DOMICILIO` varchar(200) DEFAULT NULL,
  `COD_POSTAL` varchar(20) DEFAULT NULL,
  `POBLACION` varchar(50) DEFAULT NULL,
  `PROVINCIA` varchar(500) DEFAULT NULL,
  `HABITANTES` varchar(20) DEFAULT NULL,
  `P_AUTO` varchar(100) DEFAULT NULL,
  `EMAIL` varchar(100) DEFAULT NULL,
  `WASAP` varchar(20) DEFAULT NULL,
  `COMENTARIOS` varchar(500) DEFAULT NULL,
  `Activo` bit(1) DEFAULT b'1',
  `FECREACION` timestamp NOT NULL DEFAULT current_timestamp(),
  `FEMODIFICACION` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

